function createSafeCounter(initialValue = 0) {
  let state = initialValue;

  function setState(updater) {
    if (typeof updater === 'function') {
      state = updater(state);
    } else {
      state = updater;
    }
  }

  function tick() {
    setState(prev => prev + 1);
  }

  return {
    getState: () => state,
    tick
  };
}
